//! The SDK runtime behind the component exports. Not public API: the items are `pub` only so the
//! code generated by `export_plugin!` / `#[rustic::handlers]` in plugin crates can reach them.
//!
//! State lives in thread-locals (a component instance is single-threaded): the plugin value, and
//! dispatch tables keyed by host ids (handler id -> closure, command id -> executors, task id ->
//! closure, menu id + slot -> click handler, async job name -> closure, message topic -> closure).
//! Closures are cloned out of the tables (`Rc`) before being called so they may register new
//! handlers, tasks or menus while running.

use std::any::Any;
use std::cell::{Cell, RefCell};
use std::collections::HashMap;
use std::fmt::Display;
use std::marker::PhantomData;
use std::rc::Rc;

use crate::bindings::rustic::api::commands::{CommandContext, CompleteContext};
use crate::command::{CommandCtx, CommandEntry, CommandError, CommandResult, CompleteCtx};
use crate::error::Result;
use crate::event::{ErasedHandler, Event, Events, InventoryClickEvent, InventoryCloseEvent};
use crate::menu::{MenuClick, MenuHandle, MenuRegistry};
use crate::plugin::{Ctx, Plugin};
use crate::scheduler::Task;
use crate::types::Priority;

// ---------------------------------------------------------------------------------------------
// Handler collection (`#[rustic::handlers]`) with autoref specialisation

/// Implemented by `#[rustic::handlers]` for the plugin type.
pub trait HandlerSet {
    /// Number of registrations generated.
    const COUNT: usize;
    /// Registers the collected event handlers and commands.
    fn register(ctx: &mut Ctx) -> Result<()>;
}

/// Zero-sized probe used by `export_plugin!` to call `HandlerSet::register` when the plugin
/// type implements it, and nothing otherwise.
pub struct Probe<T>(PhantomData<T>);

impl<T> Probe<T> {
    /// The probe.
    #[allow(clippy::new_without_default)]
    pub const fn new() -> Self {
        Probe(PhantomData)
    }
}

/// Chosen when `T: HandlerSet` (method found without autoref).
pub trait ViaHandlers {
    /// Registers the handlers.
    fn __rustic_register(&self, ctx: &mut Ctx) -> Result<()>;
}

impl<T: HandlerSet> ViaHandlers for Probe<T> {
    fn __rustic_register(&self, ctx: &mut Ctx) -> Result<()> {
        T::register(ctx)
    }
}

/// Fallback when the plugin has no `#[rustic::handlers]` block.
pub trait ViaNothing {
    /// Does nothing.
    fn __rustic_register(&self, ctx: &mut Ctx) -> Result<()>;
}

impl<T> ViaNothing for &Probe<T> {
    fn __rustic_register(&self, _ctx: &mut Ctx) -> Result<()> {
        Ok(())
    }
}

/// What event handlers and async jobs may return: `()` or a `Result` whose error is logged.
pub trait IntoHandlerResult {
    /// Logs an error, if any, naming the handler.
    fn report(self, handler: &str);
}

impl IntoHandlerResult for () {
    fn report(self, _handler: &str) {}
}

impl<E: Display> IntoHandlerResult for std::result::Result<(), E> {
    fn report(self, handler: &str) {
        if let Err(e) = self {
            crate::error!("handler `{handler}` failed: {e}");
        }
    }
}

/// What `#[command]` methods may return: `()` or `Result<(), E: Into<CommandError>>`.
pub trait IntoCommandResult {
    /// The command result.
    fn into_command_result(self) -> CommandResult;
}

impl IntoCommandResult for () {
    fn into_command_result(self) -> CommandResult {
        Ok(())
    }
}

impl<E: Into<CommandError>> IntoCommandResult for std::result::Result<(), E> {
    fn into_command_result(self) -> CommandResult {
        self.map_err(Into::into)
    }
}

// ---------------------------------------------------------------------------------------------
// State

pub(crate) type TimerFn = Rc<RefCell<dyn FnMut(&Task)>>;
pub(crate) type BytesFn = Box<dyn FnMut(&[u8])>;

pub(crate) enum MainTask {
    Once(Box<dyn FnOnce()>),
    Repeat(TimerFn),
}

type AsyncJob = Rc<RefCell<dyn FnMut(&[u8])>>;
type MessageHandler = Rc<RefCell<dyn FnMut(&[u8])>>;

#[derive(Default)]
struct State {
    handlers: HashMap<u32, ErasedHandler>,
    commands: HashMap<u32, Rc<CommandEntry>>,
    tasks: HashMap<u32, MainTask>,
    async_jobs: HashMap<String, AsyncJob>,
    messages: HashMap<String, MessageHandler>,
    menus: MenuRegistry,
    menu_listeners: bool,
}

thread_local! {
    static STATE: RefCell<State> = RefCell::new(State::default());
    static PLUGIN: RefCell<Option<Box<dyn Any>>> = const { RefCell::new(None) };
    static IS_MAIN: Cell<Option<bool>> = const { Cell::new(None) };
    static PLUGIN_ID: RefCell<Option<String>> = const { RefCell::new(None) };
    static IN_LIFECYCLE: Cell<bool> = const { Cell::new(false) };
}

/// Whether `load`/`enable`/`disable` is running (main-only calls made there from the async
/// instance are expected and skipped silently).
pub(crate) fn in_lifecycle() -> bool {
    IN_LIFECYCLE.with(Cell::get)
}

fn lifecycle<R>(f: impl FnOnce() -> R) -> R {
    IN_LIFECYCLE.with(|c| c.set(true));
    let r = f();
    IN_LIFECYCLE.with(|c| c.set(false));
    r
}

fn with_state<R>(f: impl FnOnce(&mut State) -> R) -> R {
    STATE.with(|s| f(&mut s.borrow_mut()))
}

/// Whether this is the main instance (asked once, then cached).
pub(crate) fn is_main() -> bool {
    IS_MAIN.with(|c| match c.get() {
        Some(v) => v,
        None => {
            let v = crate::host::call!(
                "scheduler.is-main",
                crate::bindings::rustic::api::scheduler::is_main()
            );
            c.set(Some(v));
            v
        }
    })
}

/// This plugin's id (asked once, then cached).
pub(crate) fn plugin_id() -> String {
    PLUGIN_ID.with(|c| {
        if let Some(id) = c.borrow().as_ref() {
            return id.clone();
        }
        let id = crate::server::Server::self_meta().id;
        *c.borrow_mut() = Some(id.clone());
        id
    })
}

pub(crate) fn with_plugin<P: 'static, R>(f: impl FnOnce(&mut P) -> R) -> R {
    PLUGIN.with(|cell| {
        let mut guard = cell.try_borrow_mut().unwrap_or_else(|_| {
            panic!(
                "rusticmc-api: with_plugin called while the plugin is already borrowed \
                 (from enable/load/disable or a nested with_plugin)"
            )
        });
        let plugin = guard
            .as_mut()
            .expect("rusticmc-api: the plugin is not constructed yet")
            .downcast_mut::<P>()
            .unwrap_or_else(|| {
                panic!(
                    "rusticmc-api: with_plugin::<{}> does not match the plugin type",
                    std::any::type_name::<P>()
                )
            });
        f(plugin)
    })
}

/// Runs a service-provider call on the plugin (constructing it if the host calls a service
/// before `on-load`, which it should not).
pub fn provider_call<P: Plugin + Default, R>(f: impl FnOnce(&mut P) -> R) -> R {
    ensure_plugin::<P>();
    with_plugin(f)
}

fn ensure_plugin<P: Plugin + Default>() {
    PLUGIN.with(|cell| {
        let mut slot = cell.borrow_mut();
        if slot.is_none() {
            *slot = Some(Box::new(P::default()));
        }
    });
}

pub(crate) fn add_handler(id: u32, h: ErasedHandler) {
    with_state(|s| s.handlers.insert(id, h));
}

pub(crate) fn remove_handler(id: u32) {
    with_state(|s| s.handlers.remove(&id));
}

pub(crate) fn add_command(id: u32, entry: CommandEntry) {
    with_state(|s| s.commands.insert(id, Rc::new(entry)));
}

pub(crate) fn remove_command(id: u32) {
    with_state(|s| s.commands.remove(&id));
}

pub(crate) fn add_task(id: u32, t: MainTask) {
    with_state(|s| s.tasks.insert(id, t));
}

pub(crate) fn remove_task(id: u32) {
    with_state(|s| s.tasks.remove(&id));
}

pub(crate) fn add_async_job(name: &str, f: BytesFn) {
    let job: AsyncJob = Rc::new(RefCell::new(f));
    with_state(|s| s.async_jobs.insert(name.to_owned(), job));
}

pub(crate) fn has_async_job(name: &str) -> bool {
    with_state(|s| s.async_jobs.contains_key(name))
}

pub(crate) fn add_message_handler(topic: &str, f: BytesFn) {
    let h: MessageHandler = Rc::new(RefCell::new(f));
    with_state(|s| s.messages.insert(topic.to_owned(), h));
}

pub(crate) fn with_menus<R>(f: impl FnOnce(&mut MenuRegistry) -> R) -> R {
    with_state(|s| f(&mut s.menus))
}

/// Subscribes the SDK's own menu listeners the first time a menu opens.
pub(crate) fn ensure_menu_listeners() -> Result<()> {
    if with_state(|s| s.menu_listeners) {
        return Ok(());
    }
    // Menu clicks arrive cancelled: do not ignore cancelled events here.
    Events::subscribe::<InventoryClickEvent>(Priority::Normal, false, menu_click)?;
    Events::subscribe::<InventoryCloseEvent>(Priority::Monitor, false, menu_close)?;
    with_state(|s| s.menu_listeners = true);
    Ok(())
}

fn menu_click(e: &mut InventoryClickEvent) {
    use crate::event::Cancellable;
    let Some(menu) = e.menu() else { return };
    let Ok(slot) = u32::try_from(e.slot()) else {
        return;
    };
    let Some(h) = with_menus(|m| m.handler(menu, slot)) else {
        return;
    };
    let mut click = MenuClick {
        player: e.player(),
        menu: MenuHandle::new(menu),
        slot,
        kind: e.click(),
        item: e.item(),
        cursor: e.cursor(),
        cancelled: e.is_cancelled(),
    };
    (h.borrow_mut())(&mut click);
    e.set_cancelled(click.cancelled);
}

fn menu_close(e: &mut InventoryCloseEvent) {
    let Some(menu) = e.menu() else { return };
    if let Some(on_close) = with_menus(|m| m.remove(menu)) {
        on_close(e.player());
    }
}

fn clear_tables() {
    with_state(|s| {
        s.handlers.clear();
        s.commands.clear();
        s.tasks.clear();
        s.messages.clear();
        s.menus = MenuRegistry::default();
        s.menu_listeners = false;
    });
}

// ---------------------------------------------------------------------------------------------
// Exports

/// `plugin.on-load`.
pub fn on_load<P: Plugin + Default>() -> std::result::Result<(), String> {
    ensure_plugin::<P>();
    let mut ctx = Ctx::new();
    lifecycle(|| with_plugin::<P, _>(|p| p.load(&mut ctx))).map_err(|e| e.to_string())
}

/// `plugin.on-enable`: `Plugin::enable`, then the `#[rustic::handlers]` registrations.
pub fn on_enable<P: Plugin + Default>(
    register: fn(&mut Ctx) -> Result<()>,
) -> std::result::Result<(), String> {
    ensure_plugin::<P>();
    let mut ctx = Ctx::new();
    lifecycle(|| {
        with_plugin::<P, _>(|p| p.enable(&mut ctx))?;
        register(&mut ctx)
    })
    .map_err(|e| e.to_string())
}

/// `plugin.on-disable`.
pub fn on_disable<P: Plugin + Default>() {
    let constructed = PLUGIN.with(|c| c.borrow().is_some());
    if constructed {
        let mut ctx = Ctx::new();
        lifecycle(|| with_plugin::<P, _>(|p| p.disable(&mut ctx)));
    }
    clear_tables();
}

/// `plugin.run-task`.
pub fn run_task(id: u32) {
    if is_main() {
        run_main_task(id);
    } else {
        // The SDK schedules async work with `run-async-job` (-> `run-job`), never `run-async`.
        crate::debug!("run-task {id} in the async instance: not scheduled by the SDK, ignored");
    }
}

fn run_main_task(id: u32) {
    let task = with_state(|s| match s.tasks.get(&id) {
        Some(MainTask::Repeat(f)) => Some(MainTask::Repeat(f.clone())),
        Some(MainTask::Once(_)) => s.tasks.remove(&id),
        None => None,
    });
    match task {
        Some(MainTask::Once(f)) => f(),
        Some(MainTask::Repeat(f)) => (f.borrow_mut())(&Task::main(id)),
        None => crate::debug!("run-task: unknown task {id} (cancelled?)"),
    }
}

/// `plugin.run-job`: runs the async job registered under `job` with its payload.
pub fn run_job(task: u32, job: String, payload: Vec<u8>) {
    let f = with_state(|s| s.async_jobs.get(&job).cloned());
    match f {
        Some(f) => (f.borrow_mut())(&payload),
        None => crate::warn!(
            "async task {task}: job `{job}` is not registered in this instance (register it with ctx.async_task in enable)"
        ),
    }
}

/// `plugin.execute-command`.
pub fn execute_command(id: u32, raw: CommandContext) -> std::result::Result<(), String> {
    let Some(entry) = with_state(|s| s.commands.get(&id).cloned()) else {
        return Err(CommandError::new("This command is no longer available.").to_json());
    };
    let route = entry
        .usage_routes
        .get(raw.usage as usize)
        .copied()
        .unwrap_or(0);
    let Some(exec) = entry.executors.get(route).cloned() else {
        return Err(CommandError::new("No executor for this usage.").to_json());
    };
    let mut ctx = CommandCtx::from_raw(raw, route);
    let result = (exec.borrow_mut())(&mut ctx);
    result.map_err(|e| e.to_json())
}

/// `plugin.complete-command`.
pub fn complete_command(id: u32, raw: CompleteContext) -> Vec<String> {
    let completer = with_state(|s| s.commands.get(&id).and_then(|e| e.completer.clone()));
    match completer {
        Some(c) => (c.borrow_mut())(&CompleteCtx::from_raw(raw)),
        None => Vec::new(),
    }
}

/// `plugin.on-message`.
pub fn on_message(topic: String, payload: Vec<u8>) {
    let h = with_state(|s| s.messages.get(&topic).cloned());
    match h {
        Some(h) => (h.borrow_mut())(&payload),
        None => crate::debug!("message on `{topic}` has no handler (ctx.on_message)"),
    }
}

/// `handlers.handle-*`: wraps the record, runs the closure registered for `handler`, unwraps.
pub fn dispatch<E: Event>(handler: u32, raw: E::Raw) -> E::Raw {
    let mut event = E::from_raw(raw);
    let h = with_state(|s| s.handlers.get(&handler).cloned());
    match h {
        Some(h) => (h.borrow_mut())(&mut event),
        None => crate::debug!("{}: unknown handler {handler}", E::NAME),
    }
    event.into_raw()
}

/// Implements the `handlers` export for `$guest` by forwarding every `handle-*` function to
/// [`dispatch`] with the matching typed event. Used by `export_plugin!`.
#[doc(hidden)]
#[macro_export]
macro_rules! __impl_handlers_guest {
    ($guest:ident) => {
        $crate::__impl_handlers_guest!(@impl $guest;
            handle_player_pre_login: PlayerPreLogin => PlayerPreLoginEvent,
            handle_player_join: PlayerJoin => PlayerJoinEvent,
            handle_player_quit: PlayerQuit => PlayerQuitEvent,
            handle_player_chat: PlayerChat => PlayerChatEvent,
            handle_player_command: PlayerCommand => PlayerCommandEvent,
            handle_server_command: ServerCommand => ServerCommandEvent,
            handle_player_move: PlayerMove => PlayerMoveEvent,
            handle_player_teleport: PlayerTeleport => PlayerTeleportEvent,
            handle_player_change_world: PlayerChangeWorld => PlayerChangeWorldEvent,
            handle_block_break: BlockBreak => BlockBreakEvent,
            handle_block_place: BlockPlace => BlockPlaceEvent,
            handle_player_interact: PlayerInteract => PlayerInteractEvent,
            handle_player_interact_entity: PlayerInteractEntity => PlayerInteractEntityEvent,
            handle_entity_damage: EntityDamage => EntityDamageEvent,
            handle_player_death: PlayerDeath => PlayerDeathEvent,
            handle_entity_death: EntityDeath => EntityDeathEvent,
            handle_player_respawn: PlayerRespawn => PlayerRespawnEvent,
            handle_inventory_click: InventoryClick => InventoryClickEvent,
            handle_inventory_close: InventoryClose => InventoryCloseEvent,
            handle_player_game_mode_change: PlayerGameModeChange => PlayerGameModeChangeEvent,
            handle_server_list_ping: ServerListPing => ServerListPingEvent,
            handle_plugin_message: PluginMessage => PluginMessageEvent,
            handle_chunk_load: ChunkLoad => ChunkLoadEvent,
            handle_chunk_unload: ChunkUnload => ChunkUnloadEvent,
            handle_custom_event: CustomEvent => CustomEvent,
        );
    };
    (@impl $guest:ident; $($f:ident : $raw:ident => $ev:ident),* $(,)?) => {
        impl $crate::bindings::exports::rustic::api::handlers::Guest for $guest {
            $(
                fn $f(
                    handler: u32,
                    event: $crate::bindings::rustic::api::event_types::$raw,
                ) -> $crate::bindings::rustic::api::event_types::$raw {
                    $crate::__rt::dispatch::<$crate::event::$ev>(handler, event)
                }
            )*
        }
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::command::Command;
    use crate::event::{Cancellable, PlayerJoinEvent, records};
    use crate::types::{ClickKind, Uuid};

    fn as_main() {
        IS_MAIN.with(|c| c.set(Some(true)));
    }

    #[test]
    fn dispatch_runs_the_registered_closure() {
        add_handler(
            41,
            crate::event::erase(|e: &mut PlayerJoinEvent| e.set_join_message("hi")),
        );
        let raw = records::PlayerJoin {
            player: Uuid::from_u128(1),
            name: "a".into(),
            join_message: None,
        };
        let out = dispatch::<PlayerJoinEvent>(41, raw.clone());
        assert_eq!(out.join_message.as_deref(), Some(r#"{"text":"hi"}"#));
        // Unknown handler: the event comes back unchanged.
        assert_eq!(dispatch::<PlayerJoinEvent>(999, raw.clone()), raw);
        remove_handler(41);
        assert_eq!(dispatch::<PlayerJoinEvent>(41, raw.clone()), raw);
    }

    #[test]
    fn main_tasks_once_and_repeat() {
        as_main();
        let hits = Rc::new(Cell::new(0));
        let h = hits.clone();
        add_task(5, MainTask::Once(Box::new(move || h.set(h.get() + 1))));
        let h = hits.clone();
        add_task(
            6,
            MainTask::Repeat(Rc::new(RefCell::new(move |t: &Task| {
                assert_eq!(t.id(), Some(6));
                h.set(h.get() + 10);
            }))),
        );
        run_task(5);
        run_task(5);
        run_task(6);
        run_task(6);
        assert_eq!(hits.get(), 21);
        remove_task(6);
        run_task(6);
        assert_eq!(hits.get(), 21);
    }

    #[test]
    fn commands_route_by_usage_and_complete() {
        let (_, entry) = Command::new("t")
            .usage("<a:int>")
            .route("x", |c| {
                assert_eq!(c.usage_index(), 1);
                Err("route x".into())
            })
            .executor(|c| {
                let a: i64 = c.arg("a")?;
                if a > 0 {
                    Ok(())
                } else {
                    Err("negative".into())
                }
            })
            .completer(|c| c.suggest(["alpha", "beta"]))
            .build()
            .unwrap();
        add_command(3, entry);
        let ctx = |usage: u32, a: i64| CommandContext {
            sender: crate::bindings::rustic::api::types::CommandSender::Console,
            label: "t".into(),
            usage,
            args: vec![(
                "a".into(),
                crate::bindings::rustic::api::commands::ArgValue::Integer(a),
            )],
            raw: "t".into(),
        };
        assert_eq!(execute_command(3, ctx(0, 1)), Ok(()));
        assert_eq!(
            execute_command(3, ctx(0, -1)),
            Err(r#"{"text":"negative","color":"red"}"#.into())
        );
        assert_eq!(
            execute_command(3, ctx(1, 0)),
            Err(r#"{"text":"route x","color":"red"}"#.into())
        );
        assert!(execute_command(4, ctx(0, 1)).is_err());
        let done = complete_command(
            3,
            CompleteContext {
                sender: crate::bindings::rustic::api::types::CommandSender::Console,
                raw: "t b".into(),
                argument: "a".into(),
                partial: "b".into(),
            },
        );
        assert_eq!(done, vec!["beta"]);
        remove_command(3);
    }

    #[test]
    fn messages_and_async_jobs_by_name() {
        let got = Rc::new(RefCell::new(String::new()));
        let g = got.clone();
        add_message_handler(
            "motd",
            Box::new(move |b: &[u8]| *g.borrow_mut() = String::from_utf8_lossy(b).into()),
        );
        on_message("motd".into(), b"hello".to_vec());
        on_message("other".into(), b"ignored".to_vec());
        assert_eq!(*got.borrow(), "hello");

        let g = got.clone();
        add_async_job(
            "job",
            Box::new(move |p: &[u8]| *g.borrow_mut() = String::from_utf8_lossy(p).into()),
        );
        assert!(has_async_job("job"));
        assert!(!has_async_job("nope"));
        run_job(9, "job".into(), b"\"payload\"".to_vec());
        assert_eq!(*got.borrow(), "\"payload\"");
        run_job(10, "nope".into(), vec![]);
        assert_eq!(*got.borrow(), "\"payload\"");
    }

    #[test]
    fn menu_clicks_are_routed_and_uncancelled() {
        let menu = crate::menu::Menu::new(1, "m").item(2, "stone", |c| c.allow());
        let spec = menu.spec();
        assert_eq!(spec.items.len(), 1);
        with_menus(|m| {
            let mut h = std::collections::HashMap::new();
            let handler: crate::menu::ClickHandler =
                Rc::new(RefCell::new(|c: &mut MenuClick| c.allow()));
            h.insert(2, handler);
            m.insert(11, h, None);
        });
        let mut ev = InventoryClickEvent::new(records::InventoryClick {
            player: Uuid::from_u128(1),
            menu: Some(11),
            slot: 2,
            click: ClickKind::Left,
            hotbar_button: -1,
            item: crate::ItemStack::new("stone").to_raw(),
            cursor: crate::ItemStack::empty().to_raw(),
            cancelled: true,
        });
        menu_click(&mut ev);
        assert!(!ev.is_cancelled());
        // Another slot of the menu: untouched.
        let mut other = ev.clone();
        other.set_cancelled(true);
        let mut raw = other.into_raw();
        raw.slot = 3;
        let mut other = InventoryClickEvent::new(raw);
        menu_click(&mut other);
        assert!(other.is_cancelled());
        menu_close(&mut InventoryCloseEvent::new(records::InventoryClose {
            player: Uuid::from_u128(1),
            menu: Some(11),
        }));
        assert!(with_menus(|m| m.handler(11, 2)).is_none());
    }

    #[test]
    #[should_panic(expected = "is a host import")]
    fn host_imports_panic_clearly_off_wasm() {
        let _ = crate::Player::online();
    }
}
